  Stage_123112_Desc = {
    Text = "A névoa obscureceu meus olhos, cortando minha conexão com meu próprio mundo, mas através do seu olhar, vi o passado ao qual nunca poderei retornar, as pessoas que nunca poderei encontrar novamente.\nNós somos parecidos."
  },
  Stage_123112_Name = {
    Text = "Através do Teu Olhar"
  },
  Stage_123113_Desc = {
    Text = "A névoa obscureceu meus olhos, cortando minha conexão com meu próprio mundo, mas através do seu olhar, vi o passado ao qual nunca poderei retornar, as pessoas que nunca poderei encontrar novamente.\nNós somos parecidos."
