  Stage_123113_Name = {
    Text = "Através do Teu Olhar"
  },
  Stage_125199_Desc = {
    Text = "Somente o inseto que se entrega ao amor pode ser tão frágil, tão resiliente, tão risível e, ainda assim, tão extraordinário. \n Oh querido, venha comigo ver algo ainda mais maravilhoso; vocês se cuidarão mutuamente e, a partir de agora, estarão intimamente ligados."
  },
  Stage_125199_Name = {
    Text = "Armadilha de Seda: Parte III"
  },
  Stage_125200_Desc = {
    Text = "A paixão sempre tem seu destino, nem sempre levando a envelhecer juntos, mas talvez mais frequentemente a uma morte injusta. \n Às vezes é o amor que encontra uma morte injusta, e às vezes é você."
  },
  Stage_125200_Name = {
    Text = "Morte Injusta: Loucura"
  },
  Stage_125201_Desc = {
    Text = "Seu antigo amor te deixou; por que você só começa a se arrepender agora? \n Hehe, não é tarde demais, sem pressa, veja—meu senhor. Enquanto o sol se pôr, cada lâmpada, cada vela vermelha projetará sua forma e sombra atrás da janela."
  },
  Stage_125201_Name = {
    Text = "Sombra Atrás: Parte II"
  },
  Stage_125202_Desc = {
    Text = "\"...como a cigarra que troca a pele e os ossos, isso é chamado de desmembramento e ascensão ao imortal...\" \n Oh, na verdade não é, isso é uma história absurda, mas qual é a importância? Elas oram com sangue e lágrimas, e assim, a beleza e o medo que fazem tremer ressurgem."
  },
  Stage_125202_Name = {
    Text = "Ascensão do Cadáver: VI"
  },
  Stage_125203_Desc = {
    Text = "Seu antigo amor te deixou; por que você só começa a se arrepender agora? \n Hehe, não é tarde demais, sem pressa, veja—meu senhor. Enquanto o sol se pôr, cada lâmpada, cada vela vermelha projetará sua forma e sombra atrás da janela."
  },
  Stage_125203_Name = {
    Text = "Sombra Atrás: Eu"
  },
  Stage_125204_Desc = {
    Text = "Eles se ajoelham juntos sob o altar de incenso, a deusa misteriosa sem forma, incognoscível, indefinível e inoponível. \n Oferecendo tudo, cumprindo tudo, ascendendo à única Euforia, o Caos eterno."
  },
  Stage_125204_Name = {
    Text = "Euforia: Loucura"
  },
  Stage_125205_Desc = {
    Text = "Eu gosto do seu cheiro, e eu vou provar seu inimigo por você."
  },
  Stage_125205_Name = {
    Text = "Rastreando o Cheiro: Parte II"
  },
  Stage_125206_Desc = {
    Text = "Aquela seita misteriosa flutua além dos registros históricos da antiga nação oriental, incognoscível e indefinível. Apenas um número muito reduzido de indivíduos, que ainda não pereceram e habitam eternamente na terra sem sonhos, conheceu uma vez o nome da divindade que adoravam. \n Ela é chamada de—\"@4\""
  },
  Stage_125206_Name = {
    Text = "Ordem da Graça do Inchaço: I"
  },
