  Stage_131105_Desc = {
    Text = "A gaiola imortal é tecida pelas próprias mãos dos prisioneiros.\nEles tecem pela eternidade. Nunca escaparam."
  },
  Stage_131105_Name = {Text = "Crisálida"},
  Stage_132466_Desc = {
    Text = "Exclusivo para testes internos"
  },
  Stage_132466_Name = {
    Text = "Ambiente de Teste · Capítulo do Esquecimento"
  },
  Stage_139577_Desc = {
    Text = "Ótimo, esses... não não não, quero dizer, esses gatos pretos são absolutamente terríveis!"
  },
  Stage_139577_Name = {
    Text = "Corrida do Ouro Negro"
  },
  Stage_139578_Desc = {
    Text = "Com os bolsos cheios de Prata e Cupom de ouro rosa, o general vitorioso retorna para casa carregado de espólios."
  },
  Stage_139578_Name = {
    Text = "Retorno com carga completa"
  },
  Stage_139579_Desc = {
    Text = "Você mirou no maior gato de todos. E ele mirou em você."
  },
  Stage_139579_Name = {
    Text = "O Maior Gato"
  },
  Stage_139580_Desc = {
    Text = "Mas ainda há tantos gatos restantes. Vamos lá... uma última vez?"
  },
  Stage_139580_Name = {
    Text = "faça de novo"
  },
  Stage_139581_Desc = {
    Text = "Quando o primeiro brilho de prata reluz sobre o mar escuro como breu, sua rede de capturar gatos balança com força renovada."
  },
  Stage_139581_Name = {
    Text = "Primeiro Balde de Prata"
  },
  Stage_139582_Desc = {
    Text = "Os gatos pretos estão revidando—isso significa que você está fazendo algo certo."
  },
  Stage_139582_Name = {
    Text = "Resistência à Prisão"
  },
  Stage_139583_Desc = {
    Text = "Rede maior, mais gatos—e os grandes precisam de uma rede grande. Traga-os todos!"
  },
  Stage_139583_Name = {
    Text = "Traga-os Todos!"
  },
  Stage_140299_Desc = {
    Text = "Floresça, e dance.\nVocê decidiu que, não importa quão perigoso seja o caminho à frente, jamais soltará a mão dela.\nNo momento em que nos separamos, que o mundo invertido se preencha com o \"real\"."
  },
  Stage_140299_Name = {Text = "Adeus"},
  Stage_140300_Desc = {
    Text = "A memória é como uma semente—contém todas as coisas, mas não revela nada.\nAté que a água a faça criar raízes e brotar, até que a terra a abrace, permitindo que ela extraia força da realidade."
  },
  Stage_140300_Name = {
