  Stage_143878_Name = {
    Text = "Bebida Noturna· Seis"
  },
  Stage_143879_Desc = {
    Text = "O mundo pode se tornar um inferno em um instante—mas será mesmo assim?\nÉ possível que nada tenha mudado, e que antes deste momento, você simplesmente estivesse suportando?"
