  Stage_146928_Desc = {
    Text = "Uma princesa em apuros salva por um cavaleiro — esta é uma história tradicional conhecida por todos."
  },
  Stage_146928_Name = {Text = "Princesa"},
  Stage_146929_Desc = {
    Text = "O dragão desperta, e o ódio se inflama novamente. O sopro da besta jorra das rochas, o veneno da guerra arde em chamas vivas, sem se apagar até hoje.\nA terra treme com um trovão ensurdecedor."
  },
  Stage_146929_Name = {
    Text = "Covil do Dragão"
  },
  Stage_146930_Desc = {
    Text = "O cavaleiro seguiu por caminhos desconhecidos, atravessando campos áridos e colinas, tendo apenas sua sombra como companhia.\nTalvez já estivesse morto há muito, mas sem testemunhas, até isso foi esquecido.\nO mundo é assim — silencioso como o nada."
  },
  Stage_146930_Name = {Text = "Túmulo"},
  Stage_146931_Desc = {
    Text = "Quarenta dias e quarenta noites de chuva caíram sobre a terra — não podemos continuar, e ainda assim continuaremos."
  },
  Stage_146931_Name = {
    Text = "Ilha Maçã"
  },
  Stage_146932_Desc = {
    Text = "O dragão desperta, e o ódio se inflama novamente. O sopro da besta jorra das rochas, o veneno da guerra arde em chamas vivas, sem se apagar até hoje.\nA terra treme com um trovão ensurdecedor."
  },
  Stage_146932_Name = {
    Text = "Covil do Dragão"
  },
  Stage_146933_Desc = {
    Text = "São as raízes e as flores do jardim celestial, a coroa de todos os desejos do mundo, uma abundância que jamais se esgota.\nBeba o vinho da taça, e verá aquilo que mais anseia."
  },
  Stage_146933_Name = {
    Text = "Cálice Sagrado"
  },
  Stage_146934_Desc = {
    Text = "O dragão desperta, e o ódio se inflama novamente. O sopro da besta jorra das rochas, o veneno da guerra arde em chamas vivas, sem se apagar até hoje.\nA terra treme com um trovão ensurdecedor."
  },
  Stage_146934_Name = {
    Text = "Covil do Dragão"
  },
