  Stage_20089_Desc = {
    Text = "Ela cumpriu sua promessa, e agora você finalmente pode voltar para casa juntos."
  },
  Stage_20089_Name = {
    Text = "Cabeça Dourada"
  },
  Stage_20090_Desc = {
    Text = "O Salão é o evento de arte mais importante na Cité.\nAqui, os desconhecidos buscam o sucesso, e os bem-sucedidos buscam a eternidade."
  },
  Stage_20090_Name = {
    Text = "Morte da Sra. Coral"
  },
  Stage_20091_Desc = {
    Text = "A resposta está no centro do mar."
  },
  Stage_20091_Name = {
    Text = "Meio do mar"
  },
  Stage_20092_Desc = {
    Text = "Ernst Claudel foi uma vez o senhor de Besançon.\nAté hoje, esta família é altamente estimada na região."
  },
  Stage_20092_Name = {
    Text = "Abraço epistolar"
  },
  Stage_20426_Desc = {
    Text = "O término é inevitável. Não importa o quão duro você tente ou o quanto ela lute, o passado não pode ser alterado."
  },
  Stage_20426_Name = {
    Text = "Fim resplandecente"
  },
  Stage_20427_Desc = {
    Text = "Sonhos nem sempre são doces, assim como belas melodias não tocam para sempre."
  },
  Stage_20427_Name = {
    Text = "Cortina final"
  },
  Stage_20428_Desc = {
    Text = "O rei está aprisionado em seu alto trono.\nO mundo muda, mas sua tristeza permanece inalterada."
  },
  Stage_20428_Name = {
    Text = "O Reino Dela"
  },
  Stage_20429_Desc = {
    Text = "Ela vagueia sem rumo por fragmentos de memórias.\nInconsciente, insensível, repetindo infinitamente..."
  },
  Stage_20429_Name = {
    Text = "Barreira de Memória"
  },
  Stage_20430_Desc = {
    Text = "O que está no final do labirinto? Luz do dia, noite, ou uma ilusão sem fim?\nEla precisa encontrar a resposta sozinha."
  },
  Stage_20430_Name = {
    Text = "O fim do labirinto"
  },
  Stage_20431_Desc = {
    Text = "Descendentes, mais descendentes, um fluxo interminável de descendentes...\nEles são seus únicos amantes."
  },
  Stage_20431_Name = {
    Text = "Consciência coletiva"
  },
  Stage_20432_Desc = {
    Text = "Nunca abra uma porta que não pertence a você..."
  },
  Stage_20432_Name = {Text = "Porta"},
  Stage_20433_Desc = {
    Text = "Sonhos nem sempre são doces, assim como belas melodias não tocam para sempre."
  },
