  },
  Stage_20434_Name = {
    Text = "Abraço epistolar"
  },
  Stage_20435_Desc = {
    Text = "Ele fez tudo o que pôde. Agora, deixe o tempo tecer uma nova balada."
  },
  Stage_20435_Name = {
    Text = "Nova balada"
  },
  Stage_20436_Desc = {
    Text = "Uma memória querida ou um sonho inesquecível?"
  },
  Stage_20436_Name = {
    Text = "Fios do passado"
  },
  Stage_20437_Desc = {
    Text = "Descendentes, mais descendentes, um fluxo interminável de descendentes...\nEles são seus únicos amantes."
