  },
  Stage_20438_Name = {
    Text = "Cortina final"
  },
  Stage_20439_Desc = {
    Text = "Este é um segredo entre você, gravado em suas almas e levado através da eternidade."
  },
  Stage_20439_Name = {
    Text = "Sonho ou ideal"
  },
  Stage_20440_Desc = {
    Text = "O mundo após a explosão está escuro. Você vaga no mundo espiritual, incerto sobre o que espera por você e Erica."
  },
  Stage_20440_Name = {
    Text = "A voz disse assim"
  },
  Stage_20441_Desc = {
    Text = "Outro sonho, outro passado—desta vez, você vê Erica com um corpo de carne e sangue."
  },
  Stage_20441_Name = {
    Text = "Iniciar Teste"
  },
  Stage_20442_Desc = {
