  Stage_20697_Desc = {
    Text = "A cada momento, alguém morre, assim como a cada momento, alguém nasce.\nSomente as sombras são diferentes. Elas são devoradas pelo tempo e estão atadas a esta terra de sofrimento.\nIncessantemente, nem vivas nem mortas."
  },
  Stage_20697_Name = {
    Text = "Hino das sombras"
  },
  Stage_20698_Desc = {
    Text = [[
Deus disse que eles nasceram para suportar o sofrimento e derramar sangue.
Assim como o sol deve nascer e a chuva deve cair.
Tudo acontece para o melhor.]]
  },
  Stage_20698_Name = {
    Text = "Chuva amarga"
  },
  Stage_20699_Desc = {
    Text = "Marchamos em frente pela vitória triunfante.\nVivemos pelo final perfeito."
  },
  Stage_20699_Name = {Text = "De longe"},
  Stage_20700_Desc = {
    Text = "É a única coisa viva aqui, governando tudo o que vê.\n—É o rei supremo."
  },
  Stage_20700_Name = {
    Text = "Reino das bestas"
  },
  Stage_20701_Desc = {
    Text = "Eles cruzam a fronteira entre a vida e a morte, reunindo-se através das lápides.\nDe frente, de mãos dadas, suas respirações carregam o cheiro de decomposição."
  },
  Stage_20701_Name = {
    Text = "Reunião solitária"
  },
  Stage_20702_Desc = {
    Text = "Nós somos uma coleção de insetos, ossos e lágrimas.\nEsta noite, nos reunimos aqui para testemunhar o rio fluindo com incontáveis arco-íris."
  },
  Stage_20702_Name = {
    Text = "Coleta de caça aos crânios"
  },
  Stage_20703_Desc = {
    Text = "Quando as sombras se misturam à noite e as gotas de chuva se fundem com a chuva,\no tempo para a caça se aproxima..."
  },
  Stage_20703_Name = {
    Text = "Ruptura de tempestade"
  },
