  Stage_24183_Name = {
    Text = "Nível de Julgamento da Dama Vermelha"
  },
  Stage_24184_Name = {
    Text = "Nível de Demonstração da Flor de Lodo"
  },
  Stage_24423_Desc = {
    Text = "Nenhum cidadão de Londinium recusaria um chá quente recém-preparado.\nMesmo que seja uma xícara de chá oolong de lampreia."
  },
  Stage_24423_Name = {
    Text = "Especial de Lampreia"
  },
  Stage_24424_Desc = {
    Text = "Todos escolhidos pelo destino acreditam que são a exceção.\nO destino zombeteia da probabilidade."
  },
  Stage_24424_Name = {
    Text = "Prisioneiro do Destino"
  },
  Stage_24425_Desc = {
    Text = "Corte.\nEla prometeu romper todos os laços com sua vida anterior.\nComo cortar uma fita em duas com uma tesoura."
  },
  Stage_24425_Name = {
    Text = "Dedicado a Sorel"
  },
  Stage_24426_Desc = {
    Text = "Uma vez mais, você se torna uma cativa da simpatia, mergulhando fundo em sua alma."
  },
  Stage_24426_Name = {
    Text = "Julgamento em Queda"
  },
  Stage_24427_Desc = {
    Text = "No início da história, você testemunhará uma morte magnífica.\nEmbora seja o começo, está longe de ser o fim."
  },
  Stage_24427_Name = {
    Text = "Canção do Beber"
  },
  Stage_24428_Desc = {
    Text = "O nome da garota é Sorel, o orgulho da vila.\nObediente e limpa, ela tem uma aparência branca como a neve e anda com pequenos passos, como uma verdadeira dama.\nMas ao contrário daquelas damas, ela nunca sonha."
  },
  Stage_24429_Desc = {
    Text = "Lógica é como uísque: demais dela perde seu benefício."
  },
  Stage_24429_Name = {
    Text = "Harmonia Mascarada"
  },
  Stage_24430_Desc = {
    Text = "Sob seu cuidado meticuloso, o câncer da ambição finalmente se espalhou como rosas em flor."
  },
  Stage_24430_Name = {
    Text = "Festa Vermelha"
  },
  Stage_24431_Desc = {
    Text = "Slurp. Slurp.\nNos contorcemos nas sombras, sussurramos segredos.\nCorpos gordos deixam rastros de lágrimas retorcidas sob a luz da lua—salgadas, você sabe."
  },
  Stage_24431_Name = {Text = "Ovo"},
  Stage_24432_Desc = {
    Text = "Scones, macarons e chocolate quente...\nO desejo da criada é simples: comer melhor, e ainda mais."
  },
  Stage_24432_Name = {
    Text = "Vœu de la servante"
  },
  Stage_24433_Desc = {
    Text = "Cuidado, cuidado. \nA dama que todos vocês admiram não é uma verdadeira dama. \nMas quem se importa?"
  },
  Stage_24433_Name = {
    Text = "Guia da Senhora"
  },
  Stage_24434_Desc = {
    Text = "A rosa inclina sua cabeça esbelta para os sinos, enquanto o abutre se perde entre as flores fedorentas.\nNinguém canta, ninguém fala. O mundo desaparece com sua passagem."
  },
  Stage_24434_Name = {
    Text = "Funeral da rosa"
  },
  Stage_24435_Desc = {
    Text = "Ela drena as fontes, matando pássaros inocentes.\nEla traz ventos dourados, varrendo os campos como meteoros.\nEla põe o mundo em chamas com Desejo, e depois o transforma em cinzas."
  },
  Stage_24435_Name = {
    Text = "A Dama das Camélias"
  },
