  Stage_38769_Name = {
    Text = "Miragem · Memórias IV"
  },
  Stage_38770_Desc = {
    Text = "À noite, a Rainha estava de pé na varanda do palácio, olhando para a cidade a milhares de pés abaixo.\nDia após dia, sempre que ela tentava sair do palácio, tontura, lágrimas e grandes lapsos de memória a seguiam.\n\"Você está pronta? Para enfrentar a verdade deste mundo.\"\nEla respirou fundo e saltou da varanda."
  },
  Stage_38770_Name = {
    Text = "Verdadeiro · Recordação I"
  },
  Stage_38771_Desc = {
    Text = "À noite, a Rainha estava de pé na varanda do palácio, olhando para a cidade a milhares de pés abaixo.\nDia após dia, sempre que ela tentava sair do palácio, tontura, lágrimas e grandes lapsos de memória a seguiam.\n\"Você está pronta? Para enfrentar a verdade deste mundo.\"\nEla respirou fundo e saltou da varanda."
  },
  Stage_38771_Name = {
    Text = "É verdade·Memórias III"
  },
  Stage_38772_Desc = {
    Text = "Quando ela abriu os olhos, o mundo estava à beira da destruição.\nTodos os edifícios haviam desabado, uma lama negra lambia o céu, e as brancas fresias desapareciam no vazio eterno.\nTudo estava em silêncio. Tudo parecia estar adormecido.\nSomente suas lágrimas estavam frias, resfriando seu rosto e encharcando seu cabelo."
  },
  Stage_38772_Name = {
    Text = "Bem·Lembrança IV"
  },
