  Stage_43506_Desc = {
    Text = "Adeus, disse o Gigante.\nEu retornarei à história, onde sou invencível e não posso ser parado.\nEu sou imortal."
  },
  Stage_43506_Name = {
    Text = "Chifre submerso"
  },
  Stage_43508_Desc = {
    Text = "Ó esquecido, para onde você está indo?\n—Para a distante terra de solidão. Lá, as estrelas e a lua estão em silêncio, e o oceano está calmo.\nApenas você e eu permanecemos no mundo."
  },
  Stage_43508_Name = {
    Text = "Mar sem apoio"
  },
