  Stage_46547_Name = {
    Text = "Amígdala · Emergência IV"
  },
  Stage_46548_Desc = {
    Text = "O Inferno é uma sala vazia cheia de inúmeros espelhos.\nEla não se atreve a abrir os olhos, pois tudo o que vê é seu rosto pálido e aterrorizado.\nUma voz ecoa no vazio:\nEsta é a retribuição. Em vida, você teve apenas uma concha; na morte, você se depara com inúmeras."
  },
