  Stage_51761_Desc = {
    Text = "Pela última vez, ela olhou para onde a estátua do rei uma vez esteve.\nNão havia estátua, e não havia rei."
  },
  Stage_51761_Name = {
    Text = "Recordação de Lemúria"
  },
  Stage_51762_Desc = {
    Text = "A estátua a observa de longe. Entre elas está a vasta extensão do tempo e sonhos não despertos."
  },
  Stage_51762_Name = {
    Text = "Estátua escura"
  },
  Stage_51763_Desc = {
    Text = "A esperança é o veneno mais precioso de Lemúria.\nEles cantam selvagemente, bebem profundamente e apreciam isso."
  },
  Stage_51763_Name = {
    Text = "Rito do sacerdote"
  },
  Stage_51764_Desc = {
    Text = "Estrelas, destino, deuses... Diante Deles, a justiça é inútil."
  },
  Stage_51764_Name = {
    Text = "A Virtude das Mentiras"
  },
  Stage_51765_Desc = {
    Text = "Lutando na chuva. Dizendo adeus na chuva."
  },
  Stage_51765_Name = {Text = "Na chuva"},
  Stage_51766_Desc = {
    Text = "Responda-me, meu senhor. Eu lhe oferecerei o presente mais precioso."
  },
  Stage_51766_Name = {
    Text = "Oferta do rei"
  },
  Stage_51767_Desc = {
    Text = "\"Aproveite,\" ele disse. \"Aproveite o calor humilde, aproveite o destino que foi preparado.\""
  },
  Stage_51767_Name = {
    Text = "Flesh peixe"
  },
  Stage_51768_Desc = {
    Text = "Sua vontade se tece como uma teia estrelada; ela aguarda você nos sonhos dentro da eterna Ilusão."
  },
  Stage_51768_Name = {
    Text = "Oração abissal"
  },
  Stage_51769_Desc = {
    Text = "A oração foi a primeira coisa que os Lemurianos aprenderam."
  },
  Stage_51769_Name = {Text = "Profecia"},
  Stage_51770_Desc = {
    Text = "Naquela terra tranquila e abençoada, antigos amigos se olham.\nEles vão dar as mãos e subir juntos as escadas para o Reino Divino."
  },
  Stage_51770_Name = {
    Text = "Amigo Íntimo"
  },
  Stage_51771_Desc = {
    Text = "Sangue. Lágrimas. Sacrifício. Festa. Massacre.\nOutra história das estrelas começa, mas as estrelas não se importam.\nElas brilham, como sempre brilharam."
  },
  Stage_51771_Name = {
    Text = "Ouçam, estrelas"
  },
  Stage_51772_Desc = {
    Text = "Ela sempre foi sua melhor amiga. Sempre."
  },
  Stage_51772_Name = {
    Text = "Velho amigo"
  },
  Stage_51773_Desc = {
    Text = "Beba este vinho doce. Dançe esta dança apaixonada.\nA alta sacerdotisa da terra natal entra no salão e toca seus novos seguidores."
  },
  Stage_51773_Name = {
    Text = "Festa de sangue"
  },
  Stage_51774_Desc = {
    Text = "A névoa oculta o rosto do buscador. A névoa vela o coração do rei."
  },
  Stage_51774_Name = {Text = "Mistbound"},
  Stage_51775_Desc = {
    Text = "O antigo palácio se tornou uma mera sombra, deixando apenas ecos de sonhos passados. No trono murchado repousa o esqueleto do rei, ainda narrando fábulas antigas."
  },
  Stage_51775_Name = {
    Text = "Miragem do passado"
  },
