  Stage_55391_Desc = {
    Text = "\"Deixe-me trocar a primeira rosa pelo seu primeiro poema.\""
  },
  Stage_55391_Name = {Text = "Salmo 1843"},
  Stage_55392_Desc = {
    Text = "O jardim é um quebra-cabeça, e a rosa é sua resposta."
  },
  Stage_55392_Name = {
    Text = "Aroma persistente"
  },
  Stage_55393_Desc = {
    Text = "\"Deixe-me trocar a primeira rosa pelo seu primeiro poema.\""
  },
  Stage_55393_Name = {Text = "Salmo 1843"},
  Stage_55394_Desc = {
    Text = "Não há luto, não há vento.\nApenas a tinta duradoura do poeta toca o sino da morte para o jardim."
  },
  Stage_55394_Name = {
    Text = "Lamento do jardim"
  },
  Stage_55395_Desc = {
    Text = "A estátua é a retórica do rei; o silêncio é a retórica da estátua."
  },
  Stage_55395_Name = {
    Text = "Retórica estatutária"
  },
  Stage_55396_Desc = {
    Text = "Eles se olham através do jardim.\nO jardim contém incontáveis caminhos para cada um deles, todos levando em direções diferentes."
  },
  Stage_55396_Name = {
    Text = "Jardim dos caminhos bifurcados"
  },
  Stage_55397_Desc = {
    Text = "Despeça-se dos ossos no primeiro funeral e do tempo no segundo."
  },
  Stage_55397_Name = {
    Text = "Funeral atrasado"
  },
  Stage_55398_Desc = {
    Text = "\nPoesia excelente imerge o leitor.\nA teoria estética clássica a apresenta desta forma."
  },
  Stage_55398_Name = {
    Text = "Personagem do poema"
  },
  Stage_55399_Desc = {
    Text = "As flores em flor da Cité estenderam um convite a você, convidando-o a entrar neste sonho junto com elas."
  },
  Stage_55399_Name = {
    Text = "Cidade das flores"
  },
  Stage_55400_Desc = {
    Text = "A tão chamada cidade natal não é mais do que uma mentira de longa data."
