  Stage_56404_Desc = {
    Text = "Murphy soube que não era a primeira Santidade; ao longo de milhares de anos, os corações de inúmeras garotas ecoaram um batida semelhante.\nEm incontáveis tempos e espaços, inúmeros corações se sobrepõem e pulsando."
  },
  Stage_56404_Name = {
    Text = "Fenda Temporal·Loucuras"
  },
  Stage_56404_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_56405_Desc = {
    Text = "Este é o último lugar de descanso digno para toda Vida.\nCom Aequor como o caixão e os céus e a terra como a cama, Deus repousa nas correntes oceânicas."
  },
  Stage_56405_Name = {
    Text = "Manto·Loucura"
  },
  Stage_56405_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_56407_Desc = {
    Text = "Ele desceu silenciosamente e sem emoção.\nSeu coração bate através do sangue dela, continuando a viver sem desejo."
  },
  Stage_56407_Name = {
    Text = "Sua Chegada · Loucura"
  },
  Stage_56407_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_56408_Desc = {
    Text = "Ela conta as estrelas no céu, esperando por um momento que não anticipa. \n\"Quando as estrelas se alinharem,\" no momento em que as estrelas surgem acima do mar, ela se transformará em uma delas."
  },
  Stage_56408_Name = {
    Text = "Estrela Amarela · Loucura"
  },
  Stage_56408_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_56409_Desc = {
    Text = "Ela não tinha o direito de decidir o destino do embrião implantado em seu peito.\nEla não tinha o direito de decidir para onde fugir, de quem pegar a mão, ou com quem vagar.\nDiante do destino flutuante em meio às ilusões do mar, todos eram apenas um cordeiro aguardando o abate."
  },
  Stage_56409_Name = {
    Text = "Ovelha do Sacrifício·Loucura"
  },
  Stage_56409_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_56410_Desc = {
    Text = "Não é necessário uma guilhotina para executá-la.\nFoi sua mãe quem fez isso pessoalmente."
  },
  Stage_56410_Name = {
    Text = "Executor·Loucura"
  },
  Stage_56410_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_56411_Desc = {
    Text = "Silêncio. Silêncio. Silêncio.\nSob o gelo, tudo é eterno; até a respiração está congelada. Sobrevivência e morte são sinônimos, assim como hibernação e renascimento são indistinguíveis.\nElworth nunca terá sua primavera."
  },
  Stage_56411_Name = {
    Text = "Dormant·Loucuras"
  },
  Stage_56411_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
