  Stage_58364_StageInitStateText = {Text = "Primordial"},
  Stage_58365_Desc = {
    Text = "\"Eu não tenho nada mais.\" disse a criança de rua de um olho só, \"A única coisa que tenho é esta flor para te oferecer, grande rainha.\"\nEla pegou a freésia branca, mas sentiu confusão. Parecia que esta cena se repetiu inúmeras vezes nas profundezas de sua memória.\nRepetidamente, como o labirinto que aprisionou o Minotauro."
  },
