  Stage_58378_Name = {
    Text = "Revelação · Quatro"
  },
  Stage_58379_Desc = {
    Text = "Isarau desapareceu, como se nunca tivesse existido.\nTodas as ruas e pessoas eram ilusões. Elas nasceram de seus sonhos, tomando forma dia após dia, e então:\n\"Bang—\"\nO sonho acabou. Ela nunca abriu os olhos para ver Isarau, assim como nunca abriu os olhos para se ver."
  },
