  Stage_58403_Desc = {
    Text = "A Cidade Dourada—Isarau.\nSua riqueza é inesgotável, seus desejos ilimitados.\nComo uma esponja, ela absorve o fluxo interminável de ouro e incha.\nEsse é meu capital, disse a rainha. Ela se orgulha disso"
  },
  Stage_58403_Name = {
    Text = "Cidade Dourada · Loucura"
  },
  Stage_58403_StageInitStateText = {Text = "Fim"},
  Stage_58404_Desc = {
    Text = "À noite, a Rainha estava de pé na varanda do palácio, olhando para a cidade a milhares de pés abaixo.\nDia após dia, sempre que ela tentava sair do palácio, tontura, lágrimas e grandes lapsos de memória a seguiam.\n\"Você está pronta? Para enfrentar a verdade deste mundo.\"\nEla respirou fundo e saltou da varanda."
  },
  Stage_58404_Name = {
    Text = "Verdade·Capítulo 6"
  },
