  Stage_59077_Name = {
    Text = "Fissura Primordial II"
  },
  Stage_59502_Desc = {
    Text = "Enfrente sua desesperança primordial. Enfrente seu medo primordial.\nFiquem lado a lado sem serem vistos, e então o derrubem"
  },
  Stage_59502_Name = {
    Text = "Decisivo: Sombra primordial"
  },
  Stage_59503_Desc = {
    Text = "Lembre-se do seu voto, esqueça sua oferenda."
  },
  Stage_59503_Name = {Text = "Ritual"},
  Stage_59503_StageInitStateText = {Text = "Primordial"},
  Stage_59504_Desc = {
    Text = "Em pé no Templo dos Sonhos, sustentando as ruínas desmoronadas.\nGuardando a poeira sob você, o grão que carrega todo o seu cuidado e apego."
  },
  Stage_59504_Name = {
    Text = "Fratura do sonho"
  },
  Stage_59504_StageInitStateText = {Text = "Primordial"},
  Stage_59505_Desc = {
    Text = "\"Sobreviver ou enfrentar a destruição?\""
  },
  Stage_59505_Name = {Text = "Guia"},
  Stage_59505_StageInitStateText = {Text = "Primordial"},
  Stage_59506_Desc = {
    Text = "Lembre-se do seu voto, esqueça sua oferenda."
  },
  Stage_59506_Name = {Text = "Ritual"},
