  Stage_59510_Desc = {
    Text = "Em pé no Templo dos Sonhos, sustentando as ruínas desmoronadas.\nGuardando a poeira sob você, o grão que carrega todo o seu cuidado e apego."
  },
  Stage_59510_Name = {
