  Stage_75771_Desc = {
    Text = "O mar cinza se estende interminavelmente.\nTodas as almas abandonadas se reúnem aqui, com ondas se agitando, subindo e descendo.\nElas se agrupam, riem e choram; elas te observam e aguardam o próximo companheiro."
  },
  Stage_75771_Name = {
