  Stage_7741_Name = {
    Text = "Mergulho Fantasmagórico V"
  },
  Stage_7742_Desc = {
    Text = "O ídolo em ruínas presencia suas pessoas;\nAssistindo eles sobreviverem, multiplicarem, lutarem—e em tempo, esquecerem completamente isso.\nO ídolo em ruínas anseia por seu povo...."
  },
  Stage_7742_Name = {
    Text = "Mergulho Fantasmagórico I"
  },
  Stage_7743_Desc = {
    Text = "Eles existiram muito antes das estrelas nascerem.\nEles são tanto Ilusão quanto tudo."
  },
  Stage_7743_Name = {
    Text = "Imagens Pós-Desfocadas I"
  },
  Stage_7744_Desc = {
    Text = "Eles se torcem e se fundem na escuridão, depois são cuidadosamente armazenados nas estátuas.\nEsta é uma reunião há muito aguardada."
  },
  Stage_7744_Name = {
