  Stage_7934_Name = {
    Text = "Sussurros do imortal"
  },
  Stage_7935_Desc = {
    Text = "Estátuas misteriosas vagam e tremem na escuridão.\nElas dançam ao ritmo antigo, guiadas por melodias de flauta distantes."
  },
  Stage_7935_Name = {
    Text = "Relíquia Aequor·Fissura VIII"
  },
  Stage_7936_Desc = {
    Text = "A Cidade Rai fica ao norte de Londinium, escondida entre as montanhas sem fim.\nAldeões silenciosos, olhos sempre vigilantes... cuidado, nada aqui é comum."
  },
  Stage_7936_Name = {
    Text = "Cidade do Caos II"
  },
  Stage_7937_Desc = {
