  Stage_7945_Desc = {
    Text = "Ela é o limite onde sonhos e realidade se entrelaçam, o reflexo profundo dentro de cada alma que observa o céu noturno."
  },
  Stage_7945_Name = {
    Text = "Estrelas distorcidas"
  },
  Stage_7945_StageInitStateText = {
    Text = "Pesadelo do Mar"
  },
  Stage_7946_Desc = {
    Text = "O horizonte curvado escondido nas profundezas do universo.\nEle pode te levar de uma escuridão a outra."
  },
  Stage_7946_Name = {
    Text = "Garganta de Schwarzschild I"
  },
  Stage_7947_Desc = {
    Text = "O \"Portal\" está prestes a abrir, revelando um vislumbre da verdade.\nNão é preto nem branco — a verdade é colorida, mas turva."
  },
  Stage_7947_Name = {
    Text = "Reino do Caos·Fissura III"
  },
  Stage_7948_Desc = {
    Text = "Aqui jazem as ruínas de uma cidade antiga.\nEla descansa como seu mestre."
  },
  Stage_7948_Name = {
    Text = "Ruínas de Ponape V"
  },
  Stage_7949_Desc = {
    Text = "Ele se inclina contra a cabeceira com uma postura submissa, seus olhos opacos em forma de botão mirando o vazio.\nO pequeno corpo carrega todas as lágrimas de seu dono, mas não pode oferecer palavras de conforto."
  },
  Stage_7949_Name = {
    Text = "Lágrimas da Boneca II"
  },
  Stage_7950_Desc = {
    Text = "Para sua vida e saúde, mantenha-se longe da nicotina."
  },
  Stage_7950_Name = {
    Text = "Fumaça e violeta"
  },
  Stage_7951_Desc = {
    Text = "Estátuas misteriosas vagam e tremem na escuridão.\nElas dançam ao ritmo antigo, guiadas por melodias de flauta distantes."
