  Stage_97834_Name = {
    Text = "Conto de Fadas Perfeito · Parte 1"
  },
  Stage_97835_Desc = {
    Text = "Ela sabe muito bem em seu coração: a coragem solitária não traz vitória inigualável; foi assim no passado e continua sendo até hoje."
