  Stage_97835_Name = {
    Text = "Vitória apertada"
  },
  Stage_97836_Desc = {
    Text = "O sol já está morto, e o que ficou no céu é apenas um cadáver desintegrado. \nAssim como este mundo decadente, o que foi deixado entre a densa poeira é, afinal, vida ou a ilusão da atividade da vida antes da morte?"
